const input = $input.first().json;
const headers = input.headers || {};
const token = headers['x-agendamentos-token'] || headers['X-Agendamentos-Token'] || '';

if ($env.AGENDAMENTOS_API_TOKEN && token !== $env.AGENDAMENTOS_API_TOKEN) {
  throw new Error('Token invalido.');
}

const body = input.body || input;
const valor = (v, fallback = '-') => v == null || v === '' ? fallback : String(v);
const formatarData = (valor) => {
  if (!valor) return '-';
  const partes = String(valor).slice(0, 10).split('-');
  if (partes.length !== 3) return String(valor);
  return partes[2] + '/' + partes[1] + '/' + partes[0];
};
const formatarHora = (valor) => valor ? String(valor).slice(0, 5) : '-';

const dataFormatada = formatarData(body.data_agendada);
const horaFormatada = formatarHora(body.hora_agendada);
const profissional = valor(body.colaborador || body.profissional_solicitada || body.profissional || body.funcionario, 'Equipe Massoterapia RJ');
const status = valor(body.status, 'Aprovado');
const telegramText = [
  'Agendamento atualizado - Massoterapia RJ',
  '',
  'Codigo: ' + valor(body.codigo),
  'Cliente: ' + valor(body.nome_cliente),
  'Servico: ' + valor(body.servico),
  'Profissional: ' + profissional,
  'Data: ' + dataFormatada,
  'Horario: ' + horaFormatada,
  'Local: ' + valor(body.local),
  'Status: ' + status,
].join('\n');

const linhasTabela = [
  ['Código', valor(body.codigo)],
  ['Serviço', valor(body.servico)],
  ['Profissional', profissional],
  ['Data confirmada', dataFormatada],
  ['Horário confirmado', horaFormatada],
  ['Local', valor(body.local)],
  ['Status', status]
].map(([label, content]) => '<tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">' + label + '</td><td style="padding:8px;border:1px solid #e5daca">' + content + '</td></tr>').join('');

const emailHtml = '<div style="font-family:Arial,sans-serif;max-width:620px;margin:0 auto;color:#2a2520;line-height:1.6">'
  + '<h2 style="color:#946b40">Agendamento confirmado</h2>'
  + '<p>Olá, ' + valor(body.nome_cliente, 'tudo bem') + '.</p>'
  + '<p>Seu agendamento na Massoterapia RJ foi <strong>aprovado</strong>. Confira abaixo os dados atualizados pela equipe.</p>'
  + '<table style="border-collapse:collapse;width:100%;margin:18px 0">' + linhasTabela + '</table>'
  + (body.observacoes_gerente ? '<p><strong>Observação da equipe sobre este agendamento:</strong><br>' + valor(body.observacoes_gerente) + '</p>' : '')
  + '<div style="margin-top:22px;padding-top:16px;border-top:1px solid #e5daca;font-size:14px;color:#5f5145">'
  + '<p><strong>Mensagem da equipe:</strong></p>'
  + '<p>Este é um e-mail automático enviado pelo sistema de agendamento da Massoterapia RJ com os dados da sua solicitação preenchidos.</p>'
  + '<p><strong>⚠️ Por favor, não responda este e-mail.</strong></p>'
  + '<p>Para alterações de horário, dúvidas ou suporte ao seu agendamento, entre em contato diretamente pelo WhatsApp oficial do site:</p>'
  + '<p><strong>📲 WhatsApp Massoterapia RJ: (21) 98203-3272</strong></p>'
  + '<p><strong>Massoterapia RJ</strong><br>Av. Princesa Isabel, 323 – Sala 1007<br>Copacabana – Rio de Janeiro</p>'
  + '</div></div>';

return [{
  json: {
    ...body,
    colaborador: profissional,
    profissional_solicitada: body.profissional_solicitada || profissional,
    data_formatada: dataFormatada,
    hora_formatada: horaFormatada,
    telegram_text: telegramText,
    email_subject: 'Agendamento confirmado - Massoterapia RJ',
    email_html: emailHtml
  }
}];

const destinos = String($env.TELEGRAM_CHAT_IDS || $env.TELEGRAM_CHAT_ID || '')
  .split(',')
  .map((id) => id.trim())
  .filter(Boolean);

return destinos.map((telegram_chat_id) => ({
  json: {
    ...$json,
    telegram_chat_id
  }
}));
